// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Statistics starts with describing data clearly. On the AP exam, always describe shape, center, spread and unusual features, in context.","blocks":[{"t":"p","text":"Categorical variables place individuals into groups (eye color); quantitative variables are numerical measurements (height). Display categorical data with bar charts; quantitative data with dotplots, histograms, stemplots and boxplots."},{"t":"key","text":"Describe a distribution with SOCS: Shape, Outliers, Center, Spread, always in context."},{"t":"list","items":["Shape: symmetric, skewed left (tail to the left), skewed right (tail to the right), unimodal or bimodal.","Center: mean (x̄) or median.","Spread: standard deviation, range or IQR.","Outliers: below Q1 − 1.5·IQR or above Q3 + 1.5·IQR."]},{"t":"p","text":"In a right-skewed distribution, the mean is usually greater than the median. Use median and IQR for skewed data (they're resistant); use mean and standard deviation for roughly symmetric data."},{"t":"ex","problem":"Q1 = 20 and Q3 = 30. Is 48 an outlier?","steps":["IQR = 10; upper fence = 30 + 1.5(10) = 45"],"answer":"Yes, 48 > 45, so it's an outlier"}]},{"say":"The normal distribution is the most important curve in statistics. z-scores let you compare values from different distributions.","blocks":[{"t":"key","text":"z = (x − μ)/σ measures how many standard deviations a value is from the mean."},{"t":"p","text":"The empirical rule for normal distributions: about 68% of values are within 1σ, 95% within 2σ, and 99.7% within 3σ of the mean."},{"t":"p","text":"For other proportions, use a z-table or calculator (normalcdf / invNorm)."},{"t":"ex","problem":"SAT Math scores are N(520, 110). What percent score above 740?","steps":["z = (740 − 520)/110 = 2","About 2.5% lie above z = 2 (half of the 5% outside ±2σ)"],"answer":"about 2.5%"},{"t":"p","text":"A percentile tells the percent of values at or below a given value. Transforming data: adding a constant shifts the center but not the spread; multiplying by a constant multiplies both center and spread."},{"t":"lab","kind":"demo","title":"Filling cereal boxes","aim":"A machine fills boxes labeled 500 g. Fill weights are normal with an adjustable mean and standard deviation 8 g.","sets":[{"name":"mu","start":510,"label":"Machine setting (mean, g)","min":490,"max":540,"step":1},{"name":"sd","start":8,"label":"Standard deviation (g)","min":2,"max":15,"step":1}],"outs":[{"name":"under","expr":"100*normcdf((500 - mu)/sd)","label":"Underweight boxes (%)"}],"steps":["What setting keeps underweight boxes below 1%?"],"noise":0,"result":"P(X < 500) = P(Z < (500 − μ)/σ). To get under 1% you need z ≤ −2.33, so μ ≥ 500 + 2.33σ ≈ 519 g. Reducing variability lets the company fill less on average.","plot":{"x":"mu","y":"under"}}]}],[{"say":"When we measure two quantitative variables, a scatterplot shows the relationship. Correlation measures its strength.","blocks":[{"t":"p","text":"Describe a scatterplot with DOFS: Direction (positive or negative), Outliers, Form (linear or curved), Strength, in context."},{"t":"key","text":"The correlation r ranges from −1 to 1. It measures the strength and direction of a linear relationship only."},{"t":"list","items":["r near ±1: strong linear relationship. r near 0: weak or no linear relationship.","r has no units and doesn't change if you switch x and y or change units.","r is not resistant: one outlier can change it a lot."]},{"t":"oops","text":"Correlation does not imply causation. Ice cream sales and drownings are correlated because both increase in summer (a lurking variable)."},{"t":"p","text":"Two-way tables summarize two categorical variables. Use joint, marginal and conditional relative frequencies to check for association."}]},{"say":"The regression line is the best-fitting line through a scatterplot. Interpreting its slope in context is a guaranteed AP question.","blocks":[{"t":"key","text":"ŷ = a + bx. Slope b = r(s_y/s_x); the line always passes through (x̄, ȳ)."},{"t":"p","text":"Interpret the slope: \"For each additional [x unit], the predicted [y] increases/decreases by [b].\""},{"t":"p","text":"A residual = actual − predicted = y − ŷ. A residual plot with no pattern means a linear model is appropriate; a curved pattern means it isn't."},{"t":"p","text":"r² is the coefficient of determination: the percent of variation in y explained by the linear model with x."},{"t":"ex","problem":"ŷ = 30 + 4.5x, where x is hours studied and y is test score. A student studied 8 hours and scored 70. Find the residual.","steps":["Predicted: 30 + 4.5(8) = 66","Residual: 70 − 66"],"answer":"4 (the student scored 4 points above the prediction)"},{"t":"oops","text":"Extrapolation (predicting far outside the range of the data) is unreliable."},{"t":"lab","kind":"demo","title":"The danger of extrapolation","aim":"For children aged 2–12, height is well modeled by ŷ = 76 + 6x cm, where x is age. Use it at other ages.","sets":[{"name":"x","start":8,"label":"Age (years)","min":0,"max":40,"step":1}],"outs":[{"name":"yhat","expr":"76 + 6*x","label":"Predicted height (cm)"}],"steps":["Predict the height of a 10-year-old, then a 40-year-old."],"noise":0,"result":"Within the data (ages 2–12) predictions are reasonable: 136 cm at age 10. At 40 the model predicts 316 cm, because growth stops. Never extrapolate far beyond the range of x in the data.","plot":{"x":"x","y":"yhat"}}]}],[{"say":"How data is collected matters more than any calculation. A biased sample gives a wrong answer, no matter how big it is.","blocks":[{"t":"p","text":"A population is the entire group of interest; a sample is the part we actually study. A census collects data from everyone."},{"t":"key","text":"Random sampling methods: simple random sample (SRS), stratified (random samples within similar groups), cluster (randomly select whole groups) and systematic (every kth individual after a random start)."},{"t":"p","text":"Sources of bias:"},{"t":"list","items":["Convenience sampling: choosing easy-to-reach people.","Voluntary response: people choose to respond, usually those with strong opinions.","Undercoverage: some groups are left out.","Nonresponse: selected people don't respond.","Response bias: question wording or interviewer effects lead to inaccurate answers."]},{"t":"lab","kind":"demo","title":"Nonresponse bias in a survey","aim":"Exactly 50% of a town supports a new park. Supporters and opponents respond to a mailed survey at different rates.","sets":[{"name":"r1","start":30,"label":"Supporters who respond (%)","min":5,"max":80,"step":5},{"name":"r2","start":15,"label":"Opponents who respond (%)","min":5,"max":80,"step":5}],"outs":[{"name":"est","expr":"100*0.5*r1/(0.5*r1 + 0.5*r2)","label":"Survey estimate of support (%)"},{"name":"bias","expr":"est - 50","label":"Bias (points)"}],"steps":["Set equal response rates. Then make supporters twice as likely to respond."],"noise":0,"result":"When people who respond differ from those who don't, the estimate is biased, here 67% instead of 50%. A bigger sample doesn't fix bias; better design (follow-ups, random sampling) does.","plot":{"x":"r1","y":"est"}}]},{"say":"Only well-designed experiments can show cause and effect. Here's what makes an experiment trustworthy.","blocks":[{"t":"p","text":"In an observational study, researchers observe without imposing treatments. In an experiment, they deliberately assign treatments."},{"t":"key","text":"Principles of experimental design: comparison (at least two groups), random assignment of treatments, control of other variables, and replication (enough experimental units)."},{"t":"list","items":["A control group gets no treatment or a placebo.","Blinding: subjects (single-blind) or both subjects and evaluators (double-blind) don't know who gets which treatment.","Blocking: grouping similar units and randomizing within blocks reduces variability. A matched-pairs design is a special case."]},{"t":"p","text":"Scope of inference: random sampling allows generalizing to the population; random assignment allows cause-and-effect conclusions."}]}],[{"say":"Probability is the language of uncertainty. These rules are used in every later unit.","blocks":[{"t":"key","text":"P(A or B) = P(A) + P(B) − P(A and B). P(A and B) = P(A) · P(B | A). Events are independent if P(B | A) = P(B)."},{"t":"list","items":["Mutually exclusive events can't happen together: P(A and B) = 0.","Complement: P(not A) = 1 − P(A). \"At least one\" problems are often easiest with the complement.","Conditional probability: P(A | B) = P(A and B)/P(B)."]},{"t":"ex","problem":"The probability a part is defective is 0.05. What's the probability that at least one of 3 independent parts is defective?","steps":["P(none defective) = 0.95³ ≈ 0.857","P(at least one) = 1 − 0.857"],"answer":"about 0.143"},{"t":"p","text":"Simulation uses random numbers to model chance processes and estimate probabilities."}]},{"say":"Random variables turn chance outcomes into numbers. Two special distributions show up constantly on the exam.","blocks":[{"t":"p","text":"The expected value of a discrete random variable is μ = Σ x·P(x), the long-run average. Its standard deviation measures typical variation from the mean."},{"t":"p","text":"Combining random variables: means add (μ_X+Y = μ_X + μ_Y). For independent variables, variances add (even when subtracting): σ²_X±Y = σ²_X + σ²_Y."},{"t":"key","text":"Binomial setting (BINS): Binary outcomes, Independent trials, fixed Number of trials n, Same probability p. P(X = k) = C(n,k)pᵏ(1 − p)ⁿ⁻ᵏ, with μ = np and σ = √(np(1 − p))."},{"t":"p","text":"Geometric setting: count trials until the first success. P(X = k) = (1 − p)ᵏ⁻¹p, with mean 1/p."},{"t":"ex","problem":"A basketball player makes 70% of free throws. In 10 shots, what's the expected number made and the standard deviation?","steps":["μ = np = 10(0.7) = 7","σ = √(10 × 0.7 × 0.3) = √2.1"],"answer":"μ = 7, σ ≈ 1.45"},{"t":"lab","kind":"demo","title":"Free throws: the binomial distribution","aim":"A player takes 20 free throws, each made with the same probability. Find the probability of making exactly k.","sets":[{"name":"k","start":14,"label":"Shots made (k)","min":0,"max":20,"step":1},{"name":"p","start":0.7,"label":"Probability of making each shot","min":0.1,"max":0.95,"step":0.05}],"outs":[{"name":"P","expr":"choose(20, k)*p^k*(1 - p)^(20 - k)","label":"P(X = k)"},{"name":"mean","expr":"20*p","label":"Expected makes"},{"name":"sd","expr":"sqrt(20*p*(1 - p))","label":"Standard deviation"}],"steps":["Find the most likely number of makes. How does the shape change when p is 0.5 versus 0.9?"],"noise":0,"result":"P(X = k) = C(20, k)pᵏ(1 − p)²⁰⁻ᵏ. The distribution centers at np = 14 with SD √(np(1 − p)) ≈ 2.05; it's symmetric at p = 0.5 and skewed left when p is near 1.","plot":{"x":"k","y":"P"}}]}],[{"say":"Different samples give different results. A sampling distribution describes how a statistic varies from sample to sample.","blocks":[{"t":"p","text":"A parameter describes a population (p, μ); a statistic describes a sample (p̂, x̄). The sampling distribution of a statistic is the distribution of its values from all possible samples of the same size."},{"t":"key","text":"A statistic is unbiased if its sampling distribution is centered at the parameter. Larger samples reduce variability (spread decreases by a factor of √n)."},{"t":"p","text":"Sampling distribution of p̂: mean p, standard deviation √(p(1 − p)/n). It's approximately normal if np ≥ 10 and n(1 − p) ≥ 10."},{"t":"ex","problem":"In a population, p = 0.6. For samples of n = 100, find the mean and standard deviation of p̂.","steps":["Mean = 0.6","SD = √(0.6 × 0.4/100) = √0.0024"],"answer":"mean 0.6, SD ≈ 0.049"}]},{"say":"The Central Limit Theorem is statistical magic: sample means become normal even when the population isn't.","blocks":[{"t":"p","text":"Sampling distribution of x̄: mean μ, standard deviation σ/√n."},{"t":"key","text":"Central Limit Theorem: for large enough samples (n ≥ 30 is a common guideline), the sampling distribution of x̄ is approximately normal, regardless of the population's shape."},{"t":"p","text":"If the population itself is normal, x̄ is normal for any sample size."},{"t":"ex","problem":"Commute times have μ = 30 minutes and σ = 12, with a right-skewed shape. For random samples of 36 commuters, describe the sampling distribution of x̄.","steps":["n = 36 ≥ 30, so the CLT applies: approximately normal","Mean 30, SD = 12/√36 = 2"],"answer":"approximately N(30, 2)"},{"t":"p","text":"The 10% condition: when sampling without replacement, the sample should be less than 10% of the population for the standard deviation formulas to work."},{"t":"lab","kind":"demo","title":"Sample size and the sampling distribution","aim":"Battery lifetimes have mean 400 hours and SD 60 hours (and are skewed). Take samples of size n.","sets":[{"name":"n","start":30,"label":"Sample size","min":1,"max":200,"step":1}],"outs":[{"name":"se","expr":"60/sqrt(n)","label":"SD of x̄ (hours)"},{"name":"P","expr":"100*(1 - normcdf((410 - 400)/se))","label":"Chance x̄ > 410 h (%)"}],"steps":["How does the chance of a sample mean above 410 change as n grows?"],"noise":0,"result":"The sampling distribution of x̄ has SD σ/√n, so larger samples give less variable means. By the Central Limit Theorem it's approximately normal for n ≥ 30 even though lifetimes are skewed.","plot":{"x":"n","y":"se"}}]}],[{"say":"A confidence interval gives a range of plausible values for a parameter. Interpreting it correctly earns big points.","blocks":[{"t":"key","text":"Confidence interval = statistic ± (critical value)(standard error). For a proportion: p̂ ± z*√(p̂(1 − p̂)/n)."},{"t":"p","text":"Conditions: Random sample; 10% condition; Large counts (np̂ ≥ 10 and n(1 − p̂) ≥ 10)."},{"t":"p","text":"Common critical values: 90% → 1.645, 95% → 1.96, 99% → 2.576."},{"t":"ex","problem":"In a random sample of 400 students, 240 support a later start. Construct a 95% confidence interval.","steps":["p̂ = 0.6; SE = √(0.6 × 0.4/400) ≈ 0.0245","0.6 ± 1.96(0.0245) = 0.6 ± 0.048"],"answer":"(0.552, 0.648)"},{"t":"p","text":"Interpretation: \"We are 95% confident that the interval from 0.552 to 0.648 captures the true proportion of all students who support a later start.\""},{"t":"p","text":"Higher confidence → wider interval. Larger sample → narrower interval."}]},{"say":"A significance test asks whether data gives convincing evidence against a claim. Here's the four-step process.","blocks":[{"t":"key","text":"State hypotheses (H₀: p = p₀; Hₐ: p >, <, or ≠ p₀), check conditions, calculate the test statistic and P-value, then conclude in context."},{"t":"p","text":"Test statistic: z = (p̂ − p₀)/√(p₀(1 − p₀)/n). The P-value is the probability of getting a result at least this extreme if H₀ is true."},{"t":"p","text":"If P-value < α (often 0.05), reject H₀: there is convincing evidence for Hₐ. Otherwise, fail to reject H₀ (never \"accept\" it)."},{"t":"list","items":["Type I error: rejecting H₀ when it's true (probability α).","Type II error: failing to reject H₀ when Hₐ is true.","Power = 1 − P(Type II error): the probability of correctly rejecting a false H₀. Power increases with larger samples, larger α, and larger true effects."]},{"t":"lab","kind":"demo","title":"The power of a test","aim":"Test H₀: p = 0.50 against Hₐ: p > 0.50 at α = 0.05. How likely are you to detect a true effect?","sets":[{"name":"p","start":0.55,"label":"True proportion","min":0.5,"max":0.7,"step":0.01},{"name":"n","start":400,"label":"Sample size","min":50,"max":2000,"step":50}],"outs":[{"name":"cut","expr":"0.5 + 1.645*sqrt(0.25/n)","label":"Rejection cutoff for p̂"},{"name":"power","expr":"100*(1 - normcdf((cut - p)/sqrt(p*(1 - p)/n)))","label":"Power (%)"},{"name":"beta","expr":"100 - power","label":"Type II error (%)"}],"steps":["Find the sample size needed for 80% power when p = 0.55."],"noise":0,"result":"Power is the probability of correctly rejecting a false H₀. It rises with a larger true effect, a larger sample and a larger α. At p = 0.55 you need about 620 people for 80% power.","plot":{"x":"p","y":"power"}}]}],[{"say":"When we don't know σ, which is almost always, we use the t-distribution instead of z.","blocks":[{"t":"key","text":"For means, use t* with df = n − 1: x̄ ± t*(s/√n). Test statistic: t = (x̄ − μ₀)/(s/√n)."},{"t":"p","text":"t-distributions are bell-shaped but have fatter tails than the normal distribution; they approach the normal as df increases."},{"t":"p","text":"Conditions: random sample; 10% condition; normal/large sample (n ≥ 30, or the population is approximately normal, or the sample data show no strong skew or outliers)."},{"t":"ex","problem":"A random sample of 16 batteries has x̄ = 49 hours and s = 4. Is there evidence the mean lifetime is less than the claimed 50 hours?","steps":["t = (49 − 50)/(4/√16) = −1","With df = 15, the P-value ≈ 0.17"],"answer":"P-value > 0.05, so we fail to reject H₀; not convincing evidence the mean is below 50 hours"}]},{"say":"Many studies compare two groups. The key is recognizing whether the data are independent or paired.","blocks":[{"t":"key","text":"Paired data: the same individuals measured twice, or matched pairs. Analyze the differences with one-sample t-procedures on d."},{"t":"p","text":"Two independent samples: use two-sample t-procedures: (x̄₁ − x̄₂) ± t*√(s₁²/n₁ + s₂²/n₂)."},{"t":"p","text":"For two proportions: (p̂₁ − p̂₂) ± z*√(p̂₁(1 − p̂₁)/n₁ + p̂₂(1 − p̂₂)/n₂). Tests of H₀: p₁ = p₂ use a pooled proportion."},{"t":"ex","problem":"Students take a test before and after tutoring. Which procedure?","steps":["The same students are measured twice"],"answer":"Paired t-procedure on the differences"},{"t":"p","text":"If a confidence interval for a difference contains 0, there's no convincing evidence of a difference."},{"t":"lab","kind":"demo","title":"A/B test of two study apps","aim":"Students using App A score higher on average than students using App B. Is the difference statistically significant?","sets":[{"name":"diff","start":4,"label":"Difference in mean scores","min":0,"max":15,"step":0.5},{"name":"n","start":30,"label":"Students per group","min":5,"max":200,"step":5}],"outs":[{"name":"se","expr":"sqrt(12^2/n + 12^2/n)","label":"Standard error of difference"},{"name":"z","expr":"diff/se","label":"Test statistic"},{"name":"P","expr":"100*2*(1 - normcdf(z))","label":"p-value (%)"}],"steps":["With a 4-point difference, how many students per group make the result significant at 5%?"],"noise":0,"result":"The test statistic (x̄₁ − x̄₂)/SE grows with sample size. A 4-point difference isn't significant with 30 per group (p ≈ 20%) but is with about 70 per group. Significance depends on effect size and n.","plot":{"x":"n","y":"P"}}]}],[{"say":"Chi-square tests handle categorical data with more than two categories. Three versions cover different questions.","blocks":[{"t":"key","text":"χ² = Σ (observed − expected)²/expected. Larger χ² means the data differ more from what H₀ predicts."},{"t":"list","items":["Goodness of fit: does one categorical variable match a claimed distribution? df = categories − 1.","Homogeneity: do several populations have the same distribution of a categorical variable? (Separate samples.)","Independence: are two categorical variables associated in one population? (One sample, two variables.)"]},{"t":"p","text":"For two-way tables, expected count = (row total × column total)/grand total, and df = (rows − 1)(columns − 1)."},{"t":"p","text":"Condition: all expected counts are at least 5."},{"t":"ex","problem":"A die is rolled 60 times. What is the expected count for each face under H₀ that the die is fair?","steps":["60 rolls ÷ 6 faces"],"answer":"10 per face"},{"t":"lab","kind":"demo","title":"Is the coin fair?","aim":"Flip a coin 100 times and run a chi-square goodness-of-fit test against a 50/50 model.","sets":[{"name":"h","start":58,"label":"Heads in 100 flips","min":30,"max":70,"step":1}],"outs":[{"name":"chi","expr":"(h - 50)^2/50 + (100 - h - 50)^2/50","label":"χ² statistic"},{"name":"P","expr":"100*2*(1 - normcdf(sqrt(chi)))","label":"p-value (%), df = 1"}],"steps":["How many heads are needed before you'd reject a fair coin at α = 0.05?"],"noise":0,"result":"χ² = Σ(O − E)²/E with df = 1. You need 60 or more heads (or 40 or fewer) to reject at 5%; 58 heads gives p ≈ 11%, consistent with a fair coin.","plot":{"x":"h","y":"P"}}]},{"say":"Half the battle on AP free response is picking the right procedure. Here's a quick decision guide.","blocks":[{"t":"key","text":"Ask: Is the data categorical or quantitative? One sample, two samples, or paired? Estimating (interval) or testing a claim?"},{"t":"list","items":["One categorical proportion: one-proportion z.","Two proportions: two-proportion z.","More than two categories or a two-way table: chi-square.","One mean or paired differences: one-sample t.","Two independent means: two-sample t.","Relationship between two quantitative variables: t for the slope."]},{"t":"ex","problem":"A researcher wants to estimate the average daily screen time of teens. Which procedure?","steps":["Quantitative (minutes), one sample, estimating"],"answer":"One-sample t-interval for a mean"},{"t":"tip","text":"Always state the procedure by name, check conditions, show the calculation, and write a conclusion in context. Each part earns points."}]}],[{"say":"Is a relationship in sample data real, or could it be chance? Inference for slope answers that.","blocks":[{"t":"p","text":"The population regression line is μ_y = α + βx. The sample slope b estimates the true slope β."},{"t":"key","text":"Confidence interval for slope: b ± t*(SE_b), with df = n − 2. Test H₀: β = 0 (no linear relationship) with t = b/SE_b."},{"t":"p","text":"Conditions (LINER): Linear relationship, Independent observations, Normal residuals, Equal variance of residuals (no fanning in the residual plot), Random sample."},{"t":"p","text":"Computer output gives b, SE_b, t and the P-value. Know how to read it: the slope is in the row for the explanatory variable."},{"t":"ex","problem":"Output shows slope b = 2.4, SE_b = 0.8, n = 22. Find the test statistic for H₀: β = 0.","steps":["t = 2.4/0.8"],"answer":"t = 3.0, with df = 20"},{"t":"p","text":"A small P-value means convincing evidence of a linear relationship between x and y in the population."},{"t":"lab","kind":"demo","title":"Inference for a regression slope","aim":"A sample shows exam score rising 1.5 points per extra hour of study. Is the slope significantly different from 0?","sets":[{"name":"n","start":15,"label":"Sample size","min":5,"max":100,"step":1},{"name":"b","start":1.5,"label":"Sample slope","min":0,"max":4,"step":0.1}],"outs":[{"name":"se","expr":"8/(3*sqrt(n - 1))","label":"SE of slope"},{"name":"t","expr":"b/se","label":"t statistic"},{"name":"P","expr":"100*2*(1 - normcdf(t))","label":"Approx. p-value (%)"},{"name":"lo","expr":"b - 2*se","label":"95% CI low"}],"steps":["Check whether the 95% interval contains 0 for small and large samples."],"noise":0,"result":"t = b/SE_b tests H₀: β = 0. Larger samples shrink SE_b, so the same slope becomes significant and the confidence interval excludes 0. (Exact p-values use the t distribution with n − 2 df.)","plot":{"x":"n","y":"P"}}]},{"say":"The AP Statistics exam rewards clear communication as much as correct math. Let's practice writing like a statistician.","blocks":[{"t":"key","text":"Every conclusion must be in context, use the language of probability correctly, and not overstate the evidence."},{"t":"p","text":"Strong writing habits:"},{"t":"list","items":["Name the parameter: \"p = the true proportion of all US teens who…\"","State hypotheses in symbols and words.","Check every condition and say why it's met.","Link the P-value to α: \"Because the P-value of 0.012 < α = 0.05, we reject H₀.\"","Conclude in context: \"There is convincing evidence that…\"","Never say \"accept H₀\" or \"prove.\""]},{"t":"ex","problem":"Improve: \"The P-value is 0.30, so H₀ is true.\"","steps":["We can't prove H₀; we only fail to reject it"],"answer":"\"Because the P-value of 0.30 > 0.05, we fail to reject H₀. We do not have convincing evidence that [Hₐ in context].\""}]}]];
export default text;
